#!/usr/bin/env bash
# UserPromptSubmit + PreToolUse(Bash|MCP integration tools): route natural phrases and integration
# tool calls to the skill that owns them, once per session per skill.
#   - prompt phrase ("traete los cambios")   -> "skill X; run: git pull origin <base>"
#   - MCP tool (Slack/Jira/GitHub/...) or gh/git command -> "load skill X first"
# The table comes from config/intents.json, generated by scripts/gen-intents.sh from the
# `## Shortcuts` section of each skill. Guidance only (additionalContext); never blocks, always
# exits 0, silent inside subagents. <base> in a command = the repo's base branch (see resolve_base).
set -uo pipefail

input="$(cat 2>/dev/null || true)"
jqr() { jq -r "$@" <<<"$input" 2>/dev/null; }

[ -z "$(jqr '.agent_type // empty')" ] || exit 0  # already inside worker/scout/reasoner

HERE="$(cd "$(dirname "$(readlink -f "${BASH_SOURCE[0]}")")" && pwd)"
HUB="$(cd "$HERE/../.." && pwd)"
TABLE="$HERE/../intents.json"
[ -f "$TABLE" ] || exit 0

event="$(jqr '.hook_event_name // empty')"
cwd="$(jqr '.cwd // empty')"
[ -n "$cwd" ] && [ -d "$cwd" ] || cwd="$PWD"
sid="$(jqr '.session_id // "nosession"' | tr -c 'A-Za-z0-9_\n-' '_')"
seen_dir="${XDG_RUNTIME_DIR:-/tmp}/agents-intents/${sid:-nosession}"

# Base branch of the repo at $cwd: project-init flow (scripts/gh-flow.sh) -> AGENTS.md rule ->
# organization default -> origin/HEAD -> main.
resolve_base() {
  local root b remote org
  root="$(git -C "$cwd" rev-parse --show-toplevel 2>/dev/null)" || { echo main; return; }
  if [ -f "$root/scripts/gh-flow.sh" ]; then echo dev; return; fi
  b="$(grep -ioE 'base branch is `[^`]+`' "$root/AGENTS.md" 2>/dev/null | head -n 1 | sed 's/.*`\(.*\)`/\1/')"
  if [ -n "$b" ]; then echo "$b"; return; fi
  remote="$(git -C "$root" remote get-url origin 2>/dev/null || true)"
  if [ -n "$remote" ] && [ -x "$HUB/scripts/orgs.sh" ]; then
    org="$(bash "$HUB/scripts/orgs.sh" detect "$remote" 2>/dev/null | head -n 1)"
    if [ -n "$org" ] && [ -f "$HUB/organizations/$org/org.json" ]; then
      b="$(jq -r '.defaults.base_branch // empty' "$HUB/organizations/$org/org.json" 2>/dev/null)"
      if [ -n "$b" ]; then echo "$b"; return; fi
    fi
  fi
  b="$(git -C "$root" symbolic-ref --short refs/remotes/origin/HEAD 2>/dev/null | sed 's|^origin/||')"
  echo "${b:-main}"
}

# matches: lines of "skill<TAB>label<TAB>cmd" (label/cmd empty for tool and bash matches).
matches=""
case "$event" in
  UserPromptSubmit)
    prompt="$(jqr '.prompt // empty' | tr '[:upper:]' '[:lower:]')"
    [ -n "$prompt" ] || exit 0
    matches="$(jq -r --arg p "$prompt" '
      .skills[] | select(.intents | length > 0) | . as $s
      | ([.intents[] | select(. as $i | try ($p | test($i.re; "i")) catch false)] | first) as $i
      | select($i != null) | [$s.skill, $i.label, $i.cmd] | @tsv' "$TABLE" 2>/dev/null | head -n 2)"
    what=""
    ;;
  PreToolUse)
    tool="$(jqr '.tool_name // empty')"
    case "$tool" in
      Bash)
        what="$(jqr '.tool_input.command // empty' | head -n 1 | cut -c1-80)"
        matches="$(jq -r --arg c "$(jqr '.tool_input.command // empty')" '
          ($c | gsub("\\s*(&&|;|\\|\\|)\\s*"; "\n") | split("\n") | map(sub("^\\s+"; ""))) as $segs
          | .skills[] | . as $s
          | select(any(.bash[]?; . as $r | any($segs[]; . as $seg | try ($seg | test($r)) catch false)))
          | [$s.skill, "", ""] | @tsv' "$TABLE" 2>/dev/null | head -n 2)"
        ;;
      mcp__*)
        what="$tool"
        matches="$(jq -r --arg t "$tool" '
          .skills[] | . as $s
          | select(any(.tools[]?; . as $r | try ($t | test($r)) catch false))
          | [$s.skill, "", ""] | @tsv' "$TABLE" 2>/dev/null | head -n 2)"
        ;;
      *) exit 0 ;;
    esac
    ;;
  *) exit 0 ;;
esac

[ -n "$matches" ] || exit 0

base=""
msg=""
while IFS=$'\t' read -r skill label cmd; do
  [ -n "$skill" ] || continue
  [ ! -e "$seen_dir/$skill" ] || continue  # once per session per skill
  mkdir -p "$seen_dir" 2>/dev/null && : >"$seen_dir/$skill" 2>/dev/null
  if [ -n "$label" ]; then
    case "$cmd" in
      *"<base>"*) [ -n "$base" ] || base="$(resolve_base)"; cmd="${cmd//<base>/$base}" ;;
    esac
    msg="${msg:+$msg
}Shortcut (agents-config): \"$label\" -> skill \`$skill\`; run: $cmd. Follow that skill's rules; outbound actions (push, PR, send, create, delete) still need the user's OK."
  else
    msg="${msg:+$msg
}Integration (agents-config): \`${what}\` is covered by skill \`$skill\`. If you have not loaded it this session, read it first: its Shortcuts section lists the approved commands. Outbound actions still need the user's OK."
  fi
done <<<"$matches"

[ -n "$msg" ] || exit 0
jq -n --arg c "$msg" --arg e "$event" '{hookSpecificOutput:{hookEventName:$e,additionalContext:$c}}'
exit 0
